#!/bin/sh
# Name: Audiobookshelf Sync
# Author: ABS Kindle Sync
# Icon: data:image/jpeg;base64,
# DontUseFBInk
#
# Library item for ABS Kindle Sync. Tapping it (a "scriptlet" on jailbroken Kindles) makes sure
# the service and setup screen are installed and running (bin/abs-install.sh), then opens setup.

sh /mnt/us/abs-sync/bin/abs-install.sh || exit 1

# Open it once this script has finished: the library's script launcher closes when we exit,
# and the Kindle treats that as "back", which would close a screen opened before then.
(sleep 2; lipc-set-prop com.lab126.appmgrd start "app://io.github.abskindlesync") >/dev/null 2>&1 </dev/null &
